struct S { using Type = int; };

// PHASE 1: Non-dependent names resolved during definition
void non_dependent_func() {}

template<typename T>
struct TemplateClass {
    void setup() {
        // Non-dependent call (Phase 1 lookup)
        non_dependent_func();
    }

    void process() {
        // ERROR: T::Type is a dependent name, assumed not a type.
        // T::Type x;

        // PHASE 2: Dependent names resolved during instantiation
        // Keyword required for dependent nested types
        typename T::Type y = 0;
    }
};

// Usage: TemplateClass<S> tc;
// Lookup for 'Type' happens when S is known.
